  const lines=source.split('\\n'); let out='', para=[];
  const flush=()=>{if(para.length){out+='<p>'+inline(para.join(' '))+'</p>';para=[]}};
  for(let i=0;i<lines.length;i++){
    const l=lines[i];
    if(!l.trim()){flush();continue}
    if(/^#{1,6}\\s/.test(l)){
      flush();const n=(l.match(/^#+/)[0].length), text=l.replace(/^#+\\s*/,'');
