    if(/^\\d+\\.\\s/.test(l)){flush();out+='<ol><li>'+inline(l.replace(/^\\d+\\.\\s/,''))+'</li></ol>';continue}
    if(/^\\|/.test(l)){flush();out+='<p>'+inline(l)+'</p>';continue}
    para.push(l);
  }
  flush();preview.innerHTML=out;
}
function sourceLine(line,index){
  if(!line)return '<div class="line blank" data-index="'+index+'"><br></div>';
  const heading=line.match(/^(#{1,6})(\\s+)(.*)$/);
  if(heading){
    const cls=heading[1].length===1?'h1':'h2';
    return `<div class="line ${cls}" data-index="${index}"><span class="hash">${heading[1]}</span>${heading[2]}<span class="heading-text">${inlineSource(heading[3])}</span></div>`;
  }
  return `<div class="line paragraph" data-index="${index}">${inlineSource(line)}</div>`;
}
function inlineSource(s){
  let x=esc(s);
  x=x.replace(/(\\*\\*|~~|`)(.*?)(\\*\\*|~~|`)/g,(all,a,mid,b)=>{
    if(a==='**'&&b==='**')return `<span class="syntax">**</span><strong>${mid}</strong><span class="syntax">**</span>`;
    if(a==='~~'&&b==='~~')return `<span class="syntax">~~</span><del>${mid}</del><span class="syntax">~~</span>`;
    if(a==='`'&&b==='`')return `<span class="syntax">\`</span><code>${mid}</code><span class="syntax">\`</span>`;
    return all;
  });
  x=x.replace(/(^|[^*])\\*([^*]+)\\*([^*]|$)/g,'$1<span class="syntax">*</span><em>$2</em><span class="syntax">*</span>$3');
