    const sel=window.getSelection();
    if(!sel||!sel.rangeCount||sel.isCollapsed)return;
    const range=sel.getRangeAt(0);
    let line=range.startContainer.nodeType===1?range.startContainer.closest('.line'):range.startContainer.parentElement.closest('.line');
    if(!line)return;
    const lineIndex=Number(line.dataset.index);
    const startRange=document.createRange();startRange.selectNodeContents(line);startRange.setEnd(range.startContainer,range.startOffset);
    const start=startRange.toString().length, selected=range.toString();
    let lines=source.split('\\n'), text=lines[lineIndex], before=text.slice(0,start), after=text.slice(start+selected.length);
    let left=selected,right='';
    if(action==='bold'){left='**'+selected;right='**'}
    else if(action==='italic'){left='*'+selected;right='*'}
    else if(action==='strike'){left='~~'+selected;right='~~'}
    else if(action==='heading'){left='## '+selected;right=''}
    else if(action==='ul'){left='- '+selected;right=''}
    else if(action==='ol'){left='1. '+selected;right=''}
    else if(action==='check'){left='- [ ] '+selected;right=''}
    else if(action==='quote'){left='> '+selected;right=''}
    else if(action==='code'){left='`'+selected;right='`'}
    else if(action==='link'){left='['+selected+'](url)';right=''}
    else if(action==='image'){left='!['+selected+'](image-url)';right=''}
    else if(action==='table'){left='| '+selected+' | Column |';right=''}
    lines[lineIndex]=before+left+right+after;source=lines.join('\\n');
    render();
    const target=editor.querySelector(`[data-index="${lineIndex}"]`);
    if(target){
      const walker=document.createTreeWalker(target,NodeFilter.SHOW_TEXT);let node,acc=0,from=before.length+(left.length-selected.length),to=from+selected.length;
      const r=document.createRange();let setA=false;
      while(node=walker.nextNode()){
        const end=acc+node.textContent.length;
        if(!setA&&from<=end){r.setStart(node,Math.max(0,from-acc));setA=true}
        if(to<=end){r.setEnd(node,Math.max(0,to-acc));break}
        acc=end;
      }
      sel.removeAllRanges();sel.addRange(r);
    }
    if(action==='bold'||action==='italic'||action==='strike'){
      const toast=document.getElementById('toast');toast.style.display='block';setTimeout(()=>toast.style.display='none',3000);
    }
